import * as Effect from "effect/Effect";import * as Command from "effect/cli/Command";import * as Flag from "effect/cli/Flag";import * as Argument from "effect/cli/Argument";import * as NodeServices from "@effect/platform-node/NodeServices";const c=Command.make("greet",{name:Argument.String("name"),loud:Flag.Boolean("loud")},({name,loud})=>Effect.sync(()=>console.log(loud?name.toUpperCase():name)));Effect.runPromise(Command.runWith(c,{version:"1.0.0"})(["world","--loud"]).pipe(Effect.provide(NodeServices.layer)))
